  const span = () => { const a = r.int(-lim, lim), b = r.int(-lim, lim); return a <= b ? [a, b] : [b, a]; };
  const [ax1, ax2] = span(), [ay1, ay2] = span(), [bx1, bx2] = span(), [by1, by2] = span();
  return [ax1, ay1, ax2, ay2, bx1, by1, bx2, by2];
