function coveredArea(ax1: number, ay1: number, ax2: number, ay2: number, bx1: number, by1: number, bx2: number, by2: number): number {
  const xs = [...new Set([ax1, ax2, bx1, bx2])].sort((p, q) => p - q);
  const ys = [...new Set([ay1, ay2, by1, by2])].sort((p, q) => p - q);
  let total = 0;
  for (let i = 0; i + 1 < xs.length; i++) {
    for (let j = 0; j + 1 < ys.length; j++) {
      // any point strictly inside this cell tells us who covers the whole cell
      const cx = (xs[i] + xs[i + 1]) / 2, cy = (ys[j] + ys[j + 1]) / 2;
      const inA = ax1 < cx && cx < ax2 && ay1 < cy && cy < ay2;
      const inB = bx1 < cx && cx < bx2 && by1 < cy && cy < by2;
      if (inA || inB) total += (xs[i + 1] - xs[i]) * (ys[j + 1] - ys[j]);
    }
  }
  return total;
}

