class Solution:
    def coveredArea(self, ax1: int, ay1: int, ax2: int, ay2: int, bx1: int, by1: int, bx2: int, by2: int) -> int:
        xs = sorted({ax1, ax2, bx1, bx2})
        ys = sorted({ay1, ay2, by1, by2})
        total = 0
        for x0, x1 in zip(xs, xs[1:]):
            for y0, y1 in zip(ys, ys[1:]):
                cx, cy = (x0 + x1) / 2, (y0 + y1) / 2
                in_a = ax1 < cx < ax2 and ay1 < cy < ay2
                in_b = bx1 < cx < bx2 and by1 < cy < by2
                if in_a or in_b:
                    total += (x1 - x0) * (y1 - y0)
        return total

